};

export const updateMilestone = async (id) => {
  try {
    const response = await axios.put(`${API_URL}/milestones/${id}`, { active: true });
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

// IMAGES API
export const fetchImages = async () => {
  try {
    const response = await axios.get(`${API_URL}/images`);
    return response.data;
  } catch (error) {
    return handleApiError(error, []);
  }
};

export const uploadImage = async (formData) => {
  try {
    const response = await axios.post(`${API_URL}/images`, formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    return response.data;
  } catch (error) {
    console.error('Upload error:', error);
    throw error;
  }
};

export const updateImagePosition = async (id, position) => {
  try {
    const response = await axios.put(`${API_URL}/images/${id}/position`, position);
    return response.data;
  } catch (error) {
    return handleApiError(error, { message: "Position updated" });
  }
};

